def transform(grid):
    h, w = len(grid), len(grid[0])

    # A uniform nonzero row or column separates two patterns.
    for r in range(h):
        if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r]):
            top, bottom = grid[:r], grid[r + 1:]
            if top and bottom:
                rows = min(len(top), len(bottom))
                cols = min(len(top[0]), len(bottom[0]))
                return [
                    [2 if top[i][j] and bottom[i][j] else 0 for j in range(cols)]
                    for i in range(rows)
                ]

    for c in range(w):
        if grid[0][c] != 0 and all(grid[i][c] == grid[0][c] for i in range(h)):
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            rows = min(len(left), len(right))
            cols = min(len(left[0]), len(right[0]))
            return [
                [2 if left[i][j] and right[i][j] else 0 for j in range(cols)]
                for i in range(rows)
            ]

    return [row[:] for row in grid]
